import { useState } from "react";

/* ─── Design tokens ─────────────────────────────────────── */
const C = {
  black: "#0a0a0a",
  white: "#fafaf8",
  gold: "#c9a84c",
  gray200: "#e0dbd2",
  gray400: "#9b9690",
  gray600: "#5a5650",
  red: "#c0392b",
};

/* ─── Input Style ───────────────── */
const input = (focused, error) => ({
  width: "100%",
  height: "48px",
  padding: "0 16px",
  border: `1.5px solid ${error ? C.red : focused ? C.gold : C.gray200}`,
  borderRadius: "8px",
  fontSize: "15px",
});

/* ─── MAIN COMPONENT ───────────────── */
export default function Login() {
  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [focusId, setFocusId] = useState(false);
  const [focusPw, setFocusPw] = useState(false);

  /* ── LOGIN FUNCTION ── */
  const handleLogin = () => {
    setError("");
    setSuccess("");

    // ✅ REQUIRED VALIDATION
    if (!identifier.trim()) {
      setError("Email or Phone is required");
      return;
    }
    if (!password.trim()) {
      setError("Password is required");
      return;
    }

    setLoading(true);

    setTimeout(() => {
      setLoading(false);

      // ❌ OTP LOGIC COMMENTED
      /*
      const isPhone = /^\d{10}$/.test(identifier);
      if (isPhone) {
        setShowOTP(true);
        return;
      }
      */

      // ✅ DIRECT SUCCESS LOGIN
      setSuccess("🎉 Your account is created successfully!");
    }, 1000);
  };

  return (
    <div style={{ display: "flex", minHeight: "100vh" }}>

      {/* LEFT PANEL */}
      <div className="login-left" style={{
        flex: 1,
        background: C.black,
        color: "#fff",
        padding: "40px"
      }}>
        <h2>The<span style={{ color: C.gold }}>Zuro</span></h2>
        <p>Welcome to premium shopping experience</p>
      </div>

      {/* RIGHT PANEL */}
      <div className="login-right" style={{
        width: "100%",
        maxWidth: "520px",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: "30px"
      }}>
        <div style={{ width: "100%", maxWidth: "400px" }}>

          <h2>Login</h2>

          {/* ERROR */}
          {error && (
            <div style={{ color: "red", marginBottom: "10px" }}>
              {error}
            </div>
          )}

          {/* SUCCESS */}
          {success && (
            <div style={{
              color: "green",
              marginBottom: "10px",
              fontWeight: "bold"
            }}>
              {success}
            </div>
          )}

          {/* EMAIL */}
          <input
            style={input(focusId, false)}
            placeholder="Email or Phone"
            value={identifier}
            onChange={(e) => setIdentifier(e.target.value)}
            onFocus={() => setFocusId(true)}
            onBlur={() => setFocusId(false)}
          />

          {/* PASSWORD */}
          <div style={{ position: "relative", marginTop: "15px" }}>
            <input
              style={input(focusPw, false)}
              type={showPw ? "text" : "password"}
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              onFocus={() => setFocusPw(true)}
              onBlur={() => setFocusPw(false)}
            />
            <span
              onClick={() => setShowPw(!showPw)}
              style={{
                position: "absolute",
                right: "10px",
                top: "12px",
                cursor: "pointer"
              }}
            >
              👁
            </span>
          </div>

          {/* BUTTON */}
          <button
            onClick={handleLogin}
            style={{
              width: "100%",
              marginTop: "20px",
              height: "45px",
              background: C.black,
              color: "#fff",
              border: "none",
              cursor: "pointer"
            }}
          >
            {loading ? "Loading..." : "Login"}
          </button>

        </div>
      </div>

      {/* RESPONSIVE */}
      <style>{`
        @media (max-width: 768px) {
          .login-left {
            display: none;
          }

          .login-right {
            width: 100% !important;
            padding: 20px !important;
          }
        }
      `}</style>

    </div>
  );
}
